import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { signup } from '../api';

export default function Signup() {
  const [form, setForm] = useState({ name: '', email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await signup(form);
      navigate('/verify-otp', { state: { email: form.email } });
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to signup');
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-xl mx-auto mt-16 bg-slate-800 rounded-xl shadow-lg p-8">
      <h1 className="text-2xl font-bold mb-4">Signup for Smart Budget Trip Planner</h1>
      <form onSubmit={handleSubmit} className="space-y-4">
        <input name="name" value={form.name} onChange={handleChange} placeholder="Name" className="w-full p-3 rounded-lg bg-slate-700" required />
        <input name="email" value={form.email} onChange={handleChange} placeholder="Email" className="w-full p-3 rounded-lg bg-slate-700" required />
        <input type="password" name="password" value={form.password} onChange={handleChange} placeholder="Password" className="w-full p-3 rounded-lg bg-slate-700" required />
        {error && <p className="text-red-400">{error}</p>}
        <button type="submit" disabled={loading} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-semibold transition">
          {loading ? 'Sending OTP...' : 'Signup and Send OTP'}
        </button>
      </form>
      <p className="mt-4 text-sm text-slate-300">Already have account? <Link to="/login" className="text-cyan-300">Login</Link></p>
    </motion.div>
  );
}
